using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Drawing;using System.Windows.Forms;
namespace FortsStudio {
 public static class References {
  static Dictionary<string,Dictionary<string,double>> cache=new Dictionary<string,Dictionary<string,double>>();
  static string Clean(string s){return Regex.Replace(Regex.Replace(s,@"--\[\[[\s\S]*?\]\]",""),@"--[^\r\n]*","");}
  static Dictionary<string,string> Scalars(string s){var d=new Dictionary<string,string>();foreach(Match m in Regex.Matches(Clean(s),@"(?m)^\s*([A-Za-z_]\w*)\s*=\s*([^,\r\n{}]+)"))if(!d.ContainsKey(m.Groups[1].Value))d[m.Groups[1].Value]=m.Groups[2].Value.Trim();return d;}
  static double? Resolve(string key,Dictionary<string,string> source,Dictionary<string,string> constants,int depth=0){if(depth>8)return null;string text;if(!source.TryGetValue(key,out text)&&!constants.TryGetValue(key,out text))return null;double n;if(Double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out n))return n;if(Regex.IsMatch(text,@"^[A-Za-z_]\w*$"))return Resolve(text,constants,constants,depth+1);return null;}
  public static Dictionary<string,double> Values(string game,string kind,string key){string id=game+"|"+kind+"|"+key;Dictionary<string,double> result;if(cache.TryGetValue(id,out result))return result;result=new Dictionary<string,double>();cache[id]=result;try{var template=Catalog.Templates.First(t=>t.Kind==kind&&t.Key==key);string list=File.ReadAllText(Path.Combine(game,"data",Catalog.TemplateListPath(template)));string entry=Catalog.LuaTable(list,key);var constants=Scalars(list);string weapons=Path.Combine(game,"data","weapons","weapon_list.lua");if(File.Exists(weapons))foreach(var x in Scalars(File.ReadAllText(weapons)))if(!constants.ContainsKey(x.Key))constants[x.Key]=x.Value;
    var fields=Scalars(entry);if(kind=="materials"){string parent=key=="armour"?"Armor":"Bracing";var m=Regex.Match(list,@"(?m)^"+parent+@"\s*=\s*\{");if(m.Success)foreach(var x in Scalars(Catalog.Balanced(list,list.IndexOf('{',m.Index))))if(!fields.ContainsKey(x.Key))fields[x.Key]=x.Value;}
    string script=template.Script.Length>0?File.ReadAllText(Path.Combine(game,"data",template.Script)):"";var scriptFields=Scalars(script);foreach(var p in Catalog.Parameters(kind)){var source=kind=="materials"||kind=="projectiles"||p.Scope=="list"?fields:scriptFields;var n=Resolve(p.Key,source,constants);if(n.HasValue)result[p.Key]=n.Value;}
    var offset=Regex.Match(script,@"SelectionOffset\s*=\s*\{\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)");if(offset.Success){result["SelectionOffsetX"]=Double.Parse(offset.Groups[1].Value,CultureInfo.InvariantCulture);result["SelectionOffsetY"]=Double.Parse(offset.Groups[2].Value,CultureInfo.InvariantCulture);}
   }catch{}return result;}
  public static string Format(double n){return n.ToString("0.###",CultureInfo.CurrentCulture);}
  public static string Ratio(double value,double reference){if(Math.Abs(reference)<.0000001)return "Δ "+(value>=0?"+":"")+Format(value);if(value<0||reference<0)return "Δ "+(value-reference>=0?"+":"")+Format(value-reference);return "×"+Format(value/reference);}
 }
 public partial class Studio {
  void DrawParameters(FlowLayoutPanel f,Entity entity){Header(f,"Сравнение со штатной игрой");f.Controls.Add(Theme.Label("Значения читаются из установленной Forts без активных модов. Множитель сравнивает число; он сам по себе не означает «лучше».",9));if(entity.Kind!="materials"){var choose=Theme.Combo();foreach(var t in Catalog.Templates.Where(t=>t.Kind==entity.Kind))choose.Items.Add(t);choose.SelectedItem=choose.Items.Cast<Template>().FirstOrDefault(t=>t.Key==(entity.CompareTemplate.Length>0?entity.CompareTemplate:entity.Template))??choose.Items[0];choose.SelectedIndexChanged+=(s,e)=>{entity.CompareTemplate=((Template)choose.SelectedItem).Key;Mark();ShowEntityTab(entity,"Параметры");};f.Controls.Add(choose);}else f.Controls.Add(Theme.Label("Два ориентира рядом: дерево и броня.",9));
   var query=Theme.TextBox("");f.Controls.Add(Theme.Label("Найти параметр",9,true));f.Controls.Add(query);var items=Theme.Flow();items.Dock=DockStyle.None;items.AutoSize=true;items.Padding=Padding.Empty;f.Controls.Add(items);Action rebuild=()=>{items.SuspendLayout();foreach(Control c in items.Controls.Cast<Control>().ToArray())c.Dispose();items.Controls.Clear();foreach(var p in Catalog.Parameters(entity.Kind).Where(p=>query.Text.Length==0||(UiText.Get(p.Label)+" "+p.Label+" "+p.Key).IndexOf(query.Text,StringComparison.OrdinalIgnoreCase)>=0))ReferenceNumber(items,entity,p);items.ResumeLayout();};query.TextChanged+=(s,e)=>rebuild();rebuild();
  }
  void ReferenceNumber(FlowLayoutPanel f,Entity entity,Param par){var row=new Panel{Width=490,Height=153,BackColor=Theme.Card,Margin=new Padding(0,0,0,12)};var label=Theme.Label(par.Label,10,true);label.Location=new Point(0,0);row.Controls.Add(label);var help=Theme.Label(par.Help,8);help.AutoSize=false;help.Size=new Size(480,32);help.Location=new Point(0,27);help.ForeColor=Theme.Muted;row.Controls.Add(help);double value=entity.V(par.Key,par.Default),min=par.Min,max=Math.Max(par.Max,Math.Abs(value)*2);var input=new NumericUpDown{Location=new Point(350,61),Width=133,DecimalPlaces=3,Minimum=(decimal)min,Maximum=1000000000,Value=(decimal)Math.Max(min,Math.Min(1000000000,value)),BackColor=Theme.Input,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle};var slider=new TrackBar{Location=new Point(0,58),Width=340,Height=28,Minimum=0,Maximum=1000,TickStyle=TickStyle.None,BackColor=Theme.Card};Func<double,int> pos=v=>(int)Math.Max(0,Math.Min(1000,(v-min)/(max-min)*1000));slider.Value=pos(value);var comparison=new UiLabel{Location=new Point(8,99),Size=new Size(469,42),ForeColor=Theme.Accent,BackColor=Color.FromArgb(29,47,52),Font=new Font("Segoe UI",8)};row.Controls.Add(comparison);Action update=()=>{var refs=entity.Kind=="materials"?Catalog.Templates.Where(t=>t.Kind=="materials"&&(t.Key=="bracing"||t.Key=="armour")):Catalog.Templates.Where(t=>t.Kind==entity.Kind&&t.Key==(entity.CompareTemplate.Length>0?entity.CompareTemplate:entity.Template));var lines=new List<string>();foreach(var t in refs){double n;var values=References.Values(project.GameRoot,t.Kind,t.Key);lines.Add(t.Name+": "+(values.TryGetValue(par.Key,out n)?References.Format(n)+"   →   "+References.Ratio((double)input.Value,n):"— не задано в исходнике"));}comparison.Text=String.Join("\n",lines);};bool sync=false;input.ValueChanged+=(s,e)=>{if(sync)return;sync=true;entity.Values[par.Key]=(double)input.Value;slider.Value=pos((double)input.Value);sync=false;update();Mark();};slider.ValueChanged+=(s,e)=>{if(sync)return;input.Value=(decimal)Math.Round(min+(max-min)*slider.Value/1000,3);};row.Controls.Add(input);row.Controls.Add(slider);var keyLabel=Theme.Label(par.Key,7);keyLabel.Location=new Point(1,140);keyLabel.ForeColor=Theme.Muted;row.Controls.Add(keyLabel);update();f.Controls.Add(row);}
 }
}
